
-- create Regions table 
CREATE TABLE Regions (
    region_id INT AUTO_INCREMENT PRIMARY KEY,
    region_name VARCHAR(50) UNIQUE NOT NULL
);

--  create Countries table
CREATE TABLE Country (
    country_id INT AUTO_INCREMENT PRIMARY KEY,
    country_name VARCHAR(100) UNIQUE NOT NULL,
    region_id INT,
    FOREIGN KEY (region_id) REFERENCES Regions(region_id)
);

-- create Market_Metrics table
CREATE TABLE Market_Metrics (
    metric_id INT AUTO_INCREMENT PRIMARY KEY,
    country_id INT,
    year INT NOT NULL,
    gdp_per_capita DECIMAL(15, 2),
    urban_population_percent DECIMAL(5, 2),
    fuel_price_usd_per_liter DECIMAL(5, 3),
    electricity_price_usd_per_kwh DECIMAL(5, 3),
    co2_emissions_transport_mt DECIMAL(15, 2),
    emission_regulation_score DECIMAL(5, 2),
    charging_stations INT,
    fast_chargers_share DECIMAL(5, 2),
    FOREIGN KEY (country_id) REFERENCES Country(country_id)
);

-- create Vehicle_Sales table 
CREATE TABLE Vehicle_Sales (
    sales_id INT AUTO_INCREMENT PRIMARY KEY,
    country_id INT,
    year INT NOT NULL,
    vehicle_segment ENUM('commercial', 'mass_market', 'premium'),
    powertrain_type ENUM('ICE', 'EV', 'PHEV', 'HEV'),
    ev_sales INT DEFAULT 0,
    petrol_car_sales INT DEFAULT 0,
    diesel_car_sales INT DEFAULT 0,
    total_vehicle_sales INT DEFAULT 0,
    ev_market_share DECIMAL(5, 2),
    avg_ev_range_km INT,
    ev_subsidy_usd INT,
    ev_growth_rate_yoy DECIMAL(10, 2),
    is_ev_dominant TINYINT(1),
    FOREIGN KEY (country_id) REFERENCES Country(country_id)
);


