-- 4. Vehicle_Sales

 -- edit appreviations Market_Metrics Table
ALTER TABLE Market_Metrics
  RENAME COLUMN gdp_per_capita TO gross_domestic_product_per_capita,
  RENAME COLUMN co2_emissions_transport_mt TO co2_emissions_transport_metric_tons;
  
 -- edit appreviations vehicle_sales Table
ALTER TABLE Vehicle_Sales
  RENAME COLUMN ev_sales TO electric_vehicle_sales;
 
-- KPIs 1:
SELECT
    ROUND(AVG(avg_ev_range_km), 2) AS avg_ev_range_km,
    ROUND(SUM(vs.electric_vehicle_sales) / SUM(vs.total_vehicle_sales) * 100, 2) AS ev_market_share_pct,
    SUM(vs.electric_vehicle_sales)  AS total_ev_sales,
    SUM(vs.petrol_car_sales) + SUM(vs.diesel_car_sales) AS total_ice_sales
FROM Vehicle_Sales vs;

 -- subsidy affects the ev adoption __no  
SELECT
    c.country_name,
    ROUND(AVG(vs.ev_subsidy_usd), 2) AS avg_subsidy,
    ROUND(AVG(vs.ev_market_share), 2) AS avg_ev_share
FROM Vehicle_Sales vs
JOIN country c 
    ON vs.country_id = c.country_id
GROUP BY c.country_name
ORDER BY avg_ev_share DESC;
    
   --  Does Being Rich (High GDP) Mean More EVs
SELECT 
    c.country_name,
    ROUND(AVG(mm.gross_domestic_product_per_capita), 0) AS avg_gdp_per_capita, 
    ROUND(AVG(vs.ev_market_share), 2) AS avg_ev_market_share_pct
FROM Vehicle_Sales vs
JOIN country c ON vs.country_id = c.country_id
JOIN Market_Metrics mm ON vs.country_id = mm.country_id 
                      AND vs.year = mm.year
GROUP BY c.country_name
ORDER BY avg_gdp_per_capita DESC;
     
-- EV Sales Growth Over Time (Global)
SELECT
    vs.year,
    SUM(vs.electric_vehicle_sales) AS total_ev_sales,
    SUM(vs.total_vehicle_sales) AS total_all_sales,
    ROUND(SUM(vs.electric_vehicle_sales) / SUM(vs.total_vehicle_sales) * 100, 2) AS ev_share_pct
FROM Vehicle_Sales vs
GROUP BY vs.year
ORDER BY vs.year ASC;


-- segment (commercial - mass - premium ) which has more EVs 
SELECT
    vs.vehicle_segment,
    SUM(vs.electric_vehicle_sales) AS total_ev_sales,
    ROUND(SUM(vs.electric_vehicle_sales) / SUM(vs.total_vehicle_sales) * 100, 2) AS ev_share_pct
FROM Vehicle_Sales vs
GROUP BY vs.vehicle_segment
ORDER BY ev_share_pct DESC;

-- more charging station = more EVS? 
SELECT
    c.country_name,
    ROUND(AVG(mm.charging_stations), 0) AS avg_charging_stations,
    ROUND(AVG(mm.fast_chargers_share), 2) AS avg_fast_charger_pct,
    ROUND(AVG(ev_market_share), 2) AS avg_ev_market_share_pct
FROM Vehicle_Sales vs
    left JOIN country c  ON vs.country_id = c.country_id
     left JOIN Market_Metrics mm ON vs.country_id = mm.country_id 
                           AND vs.year = mm.year
GROUP BY c.country_name
ORDER BY avg_charging_stations DESC; 

-- top 5 countries ev sales
SELECT
    c.country_name,
    SUM(v.electric_vehicle_sales) AS total_ev_sales
FROM Vehicle_Sales v
JOIN Country c
    ON v.country_id = c.country_id
GROUP BY c.country_name
ORDER BY total_ev_sales DESC
LIMIT 5;


